#!/bin/sh
# Generated by FWShift: a Google Cloud network firewall policy, created with gcloud. Read the report first: what is
# not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE                              prints the commands; needs no access to Google Cloud
#   GCLOUD_OPTS='--project my-project' sh THIS_FILE     creates the policy and its rules
#
# The policy is associated with no network: nothing changes for any traffic until you associate it:
#   gcloud compute network-firewall-policies associations create --firewall-policy fwshift --network NETWORK --global-firewall-policy
# It decides every connection of that network. Set the network's enforcement order to BEFORE_CLASSIC_FIREWALL, or
# the VPC firewall rules of the network decide first. A policy of the same name stops the script before anything is
# created; a command gcloud refuses stops it where it is (delete the policy and run it again).
set -u
DRY_RUN="${DRY_RUN:-}"
GCLOUD_OPTS="${GCLOUD_OPTS:-}"
POLICY=fwshift
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
run() {
  if [ -n "$DRY_RUN" ]; then printf 'gcloud' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gcloud "$@" $GCLOUD_OPTS --quiet >/dev/null || fail "gcloud $1 $2 $3 $4"
}
if [ -z "$DRY_RUN" ] && gcloud compute network-firewall-policies describe "$POLICY" --global $GCLOUD_OPTS >/dev/null 2>&1; then
  fail "a network firewall policy named $POLICY exists already; nothing was created"
fi

run compute network-firewall-policies create "$POLICY" --global '--description=Generated by FWShift; review the conversion report before associating it'

run compute network-firewall-policies rules create 1000 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=10.10.0.0/16,10.20.0.0/24 --dest-ip-ranges=192.0.2.53/32,192.0.2.54/32 --layer4-configs=tcp:53,udp:53 --enable-logging --description=DNS
run compute network-firewall-policies rules create 1010 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=10.10.0.0/16,10.20.0.0/24 --dest-ip-ranges=192.0.2.53/32,192.0.2.54/32 --layer4-configs=tcp:53,udp:53 --enable-logging --description=DNS
run compute network-firewall-policies rules create 1020 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=10.10.5.10/31,10.10.5.12/30,10.10.5.16/30,10.10.5.20/32 --dest-ip-ranges=10.20.0.10/32,10.20.0.25/32,203.0.113.10/32 --layer4-configs=tcp:22 --enable-logging --description=rule-2
run compute network-firewall-policies rules create 1030 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=10.10.5.10/31,10.10.5.12/30,10.10.5.16/30,10.10.5.20/32 --dest-ip-ranges=10.20.0.10/32,10.20.0.25/32,203.0.113.10/32 --layer4-configs=tcp:22 --enable-logging --description=rule-2
run compute network-firewall-policies rules create 1040 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=10.10.200.0/24 --dest-ip-ranges=0.0.0.0/1,128.0.0.0/2,192.0.0.0/23,192.0.2.0/27,192.0.2.32/28,192.0.2.48/30,192.0.2.52/32,192.0.2.55/32,192.0.2.56/29,192.0.2.64/26,192.0.2.128/25,192.0.3.0/24,192.0.4.0/22,192.0.8.0/21,192.0.16.0/20,192.0.32.0/19,192.0.64.0/18,192.0.128.0/17,192.1.0.0/16,192.2.0.0/15,192.4.0.0/14,192.8.0.0/13,192.16.0.0/12,192.32.0.0/11,192.64.0.0/10,192.128.0.0/9,193.0.0.0/8,194.0.0.0/7,196.0.0.0/6,200.0.0.0/5,208.0.0.0/4,224.0.0.0/3 --layer4-configs=all --enable-logging '--description=Guests stay out'
run compute network-firewall-policies rules create 1050 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=10.10.200.0/24 --dest-ip-ranges=0.0.0.0/1,128.0.0.0/2,192.0.0.0/23,192.0.2.0/27,192.0.2.32/28,192.0.2.48/30,192.0.2.52/32,192.0.2.55/32,192.0.2.56/29,192.0.2.64/26,192.0.2.128/25,192.0.3.0/24,192.0.4.0/22,192.0.8.0/21,192.0.16.0/20,192.0.32.0/19,192.0.64.0/18,192.0.128.0/17,192.1.0.0/16,192.2.0.0/15,192.4.0.0/14,192.8.0.0/13,192.16.0.0/12,192.32.0.0/11,192.64.0.0/10,192.128.0.0/9,193.0.0.0/8,194.0.0.0/7,196.0.0.0/6,200.0.0.0/5,208.0.0.0/4,224.0.0.0/3 --layer4-configs=all --enable-logging '--description=Guests stay out'
run compute network-firewall-policies rules create 1060 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=10.10.5.10/31,10.10.5.12/30,10.10.5.16/30,10.10.5.20/32 --dest-ip-ranges=10.30.1.0/24 --layer4-configs=tcp:22,tcp:443 --enable-logging '--description=PLC access'
run compute network-firewall-policies rules create 1070 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=10.10.5.10/31,10.10.5.12/30,10.10.5.16/30,10.10.5.20/32 --dest-ip-ranges=10.30.1.0/24 --layer4-configs=tcp:22,tcp:443 --enable-logging '--description=PLC access'
run compute network-firewall-policies rules create 1080 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=2001:db8:10::/48 --dest-ip-ranges=::/0 --layer4-configs=tcp:443 '--description=IPv6 out'
run compute network-firewall-policies rules create 1090 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=2001:db8:10::/48 --dest-ip-ranges=::/0 --layer4-configs=tcp:443 '--description=IPv6 out'
run compute network-firewall-policies rules create 1100 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=10.20.0.10/32 --layer4-configs=tcp:443 --enable-logging '--description=Public web'
run compute network-firewall-policies rules create 1110 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=10.20.0.10/32 --layer4-configs=tcp:443 --enable-logging '--description=Public web'
run compute network-firewall-policies rules create 1120 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=10.20.0.10/32 --layer4-configs=tcp:443,tcp:9000-9010 --enable-logging '--description=DMZ access / Web in'
run compute network-firewall-policies rules create 1130 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=10.20.0.10/32 --layer4-configs=tcp:443,tcp:9000-9010 --enable-logging '--description=DMZ access / Web in'
run compute network-firewall-policies rules create 1140 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=10.20.0.25/32 --layer4-configs=tcp:25 --enable-logging '--description=DMZ access / Mail in'
run compute network-firewall-policies rules create 1150 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=10.20.0.25/32 --layer4-configs=tcp:25 --enable-logging '--description=DMZ access / Mail in'
run compute network-firewall-policies rules create 1160 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=10.20.0.0/24 --layer4-configs=all '--description=DMZ access (cleanup of DMZ-Layer)'
run compute network-firewall-policies rules create 1170 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=10.20.0.0/24 --layer4-configs=all '--description=DMZ access (cleanup of DMZ-Layer)'
run compute network-firewall-policies rules create 1180 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=198.51.100.1/32 --layer4-configs=47 --enable-logging --description=Tunnels
run compute network-firewall-policies rules create 1190 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=198.51.100.1/32 --layer4-configs=47 --enable-logging --description=Tunnels
run compute network-firewall-policies rules create 1200 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=tcp:113 --enable-logging '--description=No ident'
run compute network-firewall-policies rules create 1210 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=tcp:113 --enable-logging '--description=No ident'
run compute network-firewall-policies rules create 1220 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=tcp:113 --enable-logging '--description=No ident'
run compute network-firewall-policies rules create 1230 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=tcp:113 --enable-logging '--description=No ident'
run compute network-firewall-policies rules create 1240 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --enable-logging '--description=Cleanup rule'
run compute network-firewall-policies rules create 1250 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --enable-logging '--description=Cleanup rule'
